     1→// ============================================================================
     2→// FreeLang Lock 모듈 - 행 수준 잠금 관리
     3→// ============================================================================
     4→// 목표: 다중 트랜잭션 환경에서 행 수준 잠금 (Row-Level Locking)
     5→// 원리:
     6→//   1. LockEntry: 행에 대한 잠금 기록 (row_id, tx_id, lock_type, timestamp)
     7→//   2. SHARED 잠금: 여러 TX가 동시에 읽기 가능
     8→//   3. EXCLUSIVE 잠금: 한 TX만 읽기/쓰기 가능
     9→//   4. 호환성 검사: 요청된 잠금 타입과 기존 잠금의 충돌 판단
    10→//   5. 업그레이드: SHARED → EXCLUSIVE 변환 (충돌 없을 때만)
    11→// 구조:
    12→//   - 상수 (잠금 타입, 에러 코드, 제한값)
    13→//   - LockEntry, LockTable 구조체
    14→//   - 공개 API (acquire, release, check, upgrade, stats)
    15→//   - 내부 헬퍼 (slot 할당, 호환성 검사, 개수 계산)
    16→// ============================================================================
    17→
    18→module lock {
    19→    // === 잠금 타입 ===
    20→    const LOCK_SHARED:     i32 = 1;
    21→    const LOCK_EXCLUSIVE:  i32 = 2;
    22→
    23→    // === 에러 코드 ===
    24→    const LOCK_OK:              i32 = 0;
    25→    const LOCK_ERR_CONFLICT:    i32 = 75;
    26→    const LOCK_ERR_FULL:        i32 = 76;
    27→    const LOCK_ERR_NOT_FOUND:   i32 = 77;
    28→    const LOCK_ERR_UPGRADE_FAIL: i32 = 78;
    29→
    30→    // === 제한값 ===
    31→    const MAX_LOCKS: i32 = 512;
    32→
    33→    // === 데이터 구조체 ===
    34→
    35→    // 잠금 엔트리
    36→    struct LockEntry {
    37→        row_id:     i64;    // 잠금 대상 행 ID
    38→        tx_id:      i64;    // 잠금 소유 트랜잭션 ID
    39→        lock_type:  i32;    // LOCK_SHARED 또는 LOCK_EXCLUSIVE
    40→        acquired_ts: i64;   // 잠금 획득 타임스탬프
    41→        is_used:    bool;   // 슬롯 사용 여부
    42→    }
    43→
    44→    // 잠금 테이블
    45→    struct LockTable {
    46→        entries:    [LockEntry];
    47→        lock_count: i32;
    48→    }
    49→
    50→    // 전역 잠금 테이블
    51→    let g_lock_table: LockTable = LockTable{
    52→        entries:    make([LockEntry], MAX_LOCKS),
    53→        lock_count: 0,
    54→    };
    55→
    56→    // === 공개 API ===
    57→
    58→    // lock_init: 잠금 테이블 초기화
    59→    func lock_init() -> i32 {
    60→        g_lock_table.entries = make([LockEntry], MAX_LOCKS);
    61→        g_lock_table.lock_count = 0;
    62→        return LOCK_OK;
    63→    }
    64→
    65→    // lock_acquire: 행에 대한 잠금 획득
    66→    // 호환성 검사:
    67→    //   - 같은 TX가 이미 보유: 멱등 (기존 타입 유지)
    68→    //   - EXCLUSIVE 요청 + 다른 TX 잠금: 충돌
    69→    //   - SHARED 요청 + 다른 TX EXCLUSIVE: 충돌
    70→    //   - SHARED + SHARED: OK
    71→    func lock_acquire(lt: *LockTable, row_id: i64, tx_id: i64, lock_type: i32, ts: i64) -> i32 {
    72→        let i: i32 = 0;
    73→        let max_i: i32 = MAX_LOCKS;
    74→        let existing_type: i32 = 0;
    75→        let has_existing: bool = false;
    76→
    77→        // 같은 TX가 이미 보유한 잠금 확인
    78→        while i < max_i {
    79→            if lt.entries[i].is_used && lt.entries[i].row_id == row_id && lt.entries[i].tx_id == tx_id {
    80→                has_existing = true;
    81→                existing_type = lt.entries[i].lock_type;
    82→                break;
    83→            }
    84→            i = i + 1;
    85→        }
    86→
    87→        // 같은 TX가 이미 보유: 멱등 처리 (이미 있으면 LOCK_OK)
    88→        if has_existing {
    89→            return LOCK_OK;
    90→        }
    91→
    92→        // 호환성 검사: 다른 TX의 잠금 확인
    93→        if lock_check_conflict(lt, row_id, tx_id, lock_type) {
    94→            return LOCK_ERR_CONFLICT;
    95→        }
    96→
    97→        // 빈 슬롯 할당
    98→        let slot: i32 = 0;
    99→        let ok: bool = false;
   100→        slot, ok = lt_alloc_slot(lt);
   101→        if !ok {
   102→            return LOCK_ERR_FULL;
   103→        }
   104→
   105→        // 잠금 기록
   106→        lt.entries[slot] = LockEntry{
   107→            row_id:     row_id,
   108→            tx_id:      tx_id,
   109→            lock_type:  lock_type,
   110→            acquired_ts: ts,
   111→            is_used:    true,
   112→        };
   113→        lt.lock_count = lt.lock_count + 1;
   114→
   115→        return LOCK_OK;
   116→    }
   117→
   118→    // lock_release: 트랜잭션이 보유한 모든 잠금 해제
   119→    func lock_release(lt: *LockTable, tx_id: i64) -> i32 {
   120→        let i: i32 = 0;
   121→        let max_i: i32 = MAX_LOCKS;
   122→        let released_count: i32 = 0;
   123→
   124→        while i < max_i {
   125→            if lt.entries[i].is_used && lt.entries[i].tx_id == tx_id {
   126→                lt.entries[i].is_used = false;
   127→                lt.lock_count = lt.lock_count - 1;
   128→                released_count = released_count + 1;
   129→            }
   130→            i = i + 1;
   131→        }
   132→
   133→        return released_count;
   134→    }
   135→
   136→    // lock_check_conflict: 주어진 잠금 요청이 기존 잠금과 충돌하는지 확인
   137→    // 충돌 조건:
   138→    //   - 요청이 EXCLUSIVE인 경우: 같은 행의 다른 TX 잠금 모두 충돌
   139→    //   - 요청이 SHARED이고, 기존이 EXCLUSIVE: 충돌
   140→    //   - SHARED + SHARED: 충돌 없음
   141→    func lock_check_conflict(lt: *LockTable, row_id: i64, tx_id: i64, lock_type: i32) -> bool {
   142→        let i: i32 = 0;
   143→        let max_i: i32 = MAX_LOCKS;
   144→
   145→        while i < max_i {
   146→            if lt.entries[i].is_used && lt.entries[i].row_id == row_id && lt.entries[i].tx_id != tx_id {
   147→                let existing_type: i32 = lt.entries[i].lock_type;
   148→
   149→                // EXCLUSIVE 요청이면 다른 TX 잠금은 모두 충돌
   150→                if lock_type == LOCK_EXCLUSIVE {
   151→                    return true;
   152→                }
   153→
   154→                // SHARED 요청이고 기존이 EXCLUSIVE이면 충돌
   155→                if lock_type == LOCK_SHARED && existing_type == LOCK_EXCLUSIVE {
   156→                    return true;
   157→                }
   158→
   159→                // SHARED + SHARED는 충돌 없음 (계속 루프)
   160→            }
   161→            i = i + 1;
   162→        }
   163→
   164→        return false;
   165→    }
   166→
   167→    // lock_upgrade: SHARED 잠금을 EXCLUSIVE로 업그레이드
   168→    // 조건: 같은 행의 다른 TX SHARED 잠금이 없어야 함
   169→    func lock_upgrade(lt: *LockTable, row_id: i64, tx_id: i64) -> i32 {
   170→        let existing_type: i32 = 0;
   171→        let ok: bool = false;
   172→
   173→        // 현재 잠금 타입 확인
   174→        existing_type, ok = lock_get_type(lt, row_id, tx_id);
   175→        if !ok {
   176→            return LOCK_ERR_NOT_FOUND;
   177→        }
   178→
   179→        // 이미 EXCLUSIVE이면 업그레이드 실패
   180→        if existing_type == LOCK_EXCLUSIVE {
   181→            return LOCK_ERR_UPGRADE_FAIL;
   182→        }
   183→
   184→        // 다른 TX의 SHARED 잠금 개수 확인
   185→        let other_shared_count: i32 = 0;
   186→        other_shared_count = lt_count_shared_other(lt, row_id, tx_id);
   187→        if other_shared_count > 0 {
   188→            return LOCK_ERR_UPGRADE_FAIL;
   189→        }
   190→
   191→        // EXCLUSIVE로 변경
   192→        let i: i32 = 0;
   193→        let max_i: i32 = MAX_LOCKS;
   194→        while i < max_i {
   195→            if lt.entries[i].is_used && lt.entries[i].row_id == row_id && lt.entries[i].tx_id == tx_id {
   196→                lt.entries[i].lock_type = LOCK_EXCLUSIVE;
   197→                return LOCK_OK;
   198→            }
   199→            i = i + 1;
   200→        }
   201→
   202→        return LOCK_ERR_NOT_FOUND;
   203→    }
   204→
   205→    // lock_get_type: 주어진 행의 TX 잠금 타입 조회
   206→    func lock_get_type(lt: *LockTable, row_id: i64, tx_id: i64) -> (i32, bool) {
   207→        let i: i32 = 0;
   208→        let max_i: i32 = MAX_LOCKS;
   209→
   210→        while i < max_i {
   211→            if lt.entries[i].is_used && lt.entries[i].row_id == row_id && lt.entries[i].tx_id == tx_id {
   212→                return (lt.entries[i].lock_type, true);
   213→            }
   214→            i = i + 1;
   215→        }
   216→
   217→        return (0, false);
   218→    }
   219→
   220→    // lock_stats: 잠금 테이블 통계
   221→    func lock_stats(lt: *LockTable) -> string {
   222→        let count_str: string = i64_to_string(i32_to_i64(lt.lock_count));
   223→        let max_str: string = i64_to_string(i32_to_i64(MAX_LOCKS));
   224→        return "LockTable: " + count_str + "/" + max_str;
   225→    }
   226→
   227→    // === 내부 헬퍼 함수 ===
   228→
   229→    // lt_alloc_slot: 빈 슬롯 할당
   230→    func lt_alloc_slot(lt: *LockTable) -> (i32, bool) {
   231→        let i: i32 = 0;
   232→        let max_i: i32 = MAX_LOCKS;
   233→
   234→        while i < max_i {
   235→            if !lt.entries[i].is_used {
   236→                return (i, true);
   237→            }
   238→            i = i + 1;
   239→        }
   240→
   241→        return (-1, false);
   242→    }
   243→
   244→    // lt_has_lock: 주어진 행에 TX가 보유한 잠금이 있는지 확인
   245→    @inline
   246→    func lt_has_lock(lt: *LockTable, row_id: i64, tx_id: i64) -> (i32, bool) {
   247→        let i: i32 = 0;
   248→        let max_i: i32 = MAX_LOCKS;
   249→
   250→        while i < max_i {
   251→            if lt.entries[i].is_used && lt.entries[i].row_id == row_id && lt.entries[i].tx_id == tx_id {
   252→                return (lt.entries[i].lock_type, true);
   253→            }
   254→            i = i + 1;
   255→        }
   256→
   257→        return (0, false);
   258→    }
   259→
   260→    // lt_has_exclusive_other: 주어진 행에 다른 TX의 EXCLUSIVE 잠금이 있는지 확인
   261→    @inline
   262→    func lt_has_exclusive_other(lt: *LockTable, row_id: i64, tx_id: i64) -> bool {
   263→        let i: i32 = 0;
   264→        let max_i: i32 = MAX_LOCKS;
   265→
   266→        while i < max_i {
   267→            if lt.entries[i].is_used &&
   268→               lt.entries[i].row_id == row_id &&
   269→               lt.entries[i].tx_id != tx_id &&
   270→               lt.entries[i].lock_type == LOCK_EXCLUSIVE {
   271→                return true;
   272→            }
   273→            i = i + 1;
   274→        }
   275→
   276→        return false;
   277→    }
   278→
   279→    // lt_has_any_other: 주어진 행에 다른 TX의 잠금이 있는지 확인
   280→    @inline
   281→    func lt_has_any_other(lt: *LockTable, row_id: i64, tx_id: i64) -> bool {
   282→        let i: i32 = 0;
   283→        let max_i: i32 = MAX_LOCKS;
   284→
   285→        while i < max_i {
   286→            if lt.entries[i].is_used &&
   287→               lt.entries[i].row_id == row_id &&
   288→               lt.entries[i].tx_id != tx_id {
   289→                return true;
   290→            }
   291→            i = i + 1;
   292→        }
   293→
   294→        return false;
   295→    }
   296→
   297→    // lt_count_shared_other: 주어진 행의 다른 TX SHARED 잠금 개수
   298→    func lt_count_shared_other(lt: *LockTable, row_id: i64, tx_id: i64) -> i32 {
   299→        let i: i32 = 0;
   300→        let max_i: i32 = MAX_LOCKS;
   301→        let count: i32 = 0;
   302→
   303→        while i < max_i {
   304→            if lt.entries[i].is_used &&
   305→               lt.entries[i].row_id == row_id &&
   306→               lt.entries[i].tx_id != tx_id &&
   307→               lt.entries[i].lock_type == LOCK_SHARED {
   308→                count = count + 1;
   309→            }
   310→            i = i + 1;
   311→        }
   312→
   313→        return count;
   314→    }
   315→
   316→    // === 숫자 변환 헬퍼 ===
   317→
   318→    // i32_to_i64: i32를 i64로 변환
   319→    @inline
   320→    func i32_to_i64(val: i32) -> i64 {
   321→        return val as i64;
   322→    }
   323→
   324→    // i64_to_string: i64를 문자열로 변환
   325→    func i64_to_string(val: i64) -> string {
   326→        if val == 0 {
   327→            return "0";
   328→        }
   329→
   330→        let negative: bool = val < 0;
   331→        let abs_val: i64 = val;
   332→        if negative {
   333→            abs_val = 0 - val;
   334→        }
   335→
   336→        let result: string = "";
   337→        while abs_val > 0 {
   338→            let digit: i64 = abs_val % 10;
   339→            let digit_char: string = i64_digit_to_char(digit);
   340→            result = digit_char + result;
   341→            abs_val = abs_val / 10;
   342→        }
   343→
   344→        if negative {
   345→            result = "-" + result;
   346→        }
   347→
   348→        return result;
   349→    }
