     1→// ============================================================================
     2→// FreeLang MVCC (Multi-Version Concurrency Control) 모듈
     3→// ============================================================================
     4→// 목표: 다중 트랜잭션 동시 실행을 위한 MVCC 구현
     5→// 원리:
     6→//   1. 각 행의 값에 대해 다양한 버전 유지 (행 변경 이력)
     7→//   2. 각 트랜잭션은 시작 시점의 스냅샷에서만 데이터 읽음 (일관성)
     8→//   3. 쓰기 충돌 감지: 같은 (row_id, col_idx)를 건드린 미커밋 트랜잭션 확인
     9→//   4. 커밋: 모든 버전의 created_ts와 이전 버전의 deleted_ts 설정
    10→//   5. 가비지 컬렉션: min_visible_ts보다 오래된 버전 삭제
    11→//
    12→// 구조:
    13→//   - 상수 (MAX_VERSIONS=2048, MVCC_OK=0, 에러코드 70-74)
    14→//   - VersionEntry 구조체 (행, 열, 값들, 타입, 타임스탐프, 커밋 상태)
    15→//   - VersionStore 구조체 (버전 풀, 카운터, 다음 슬롯)
    16→//   - 공개 API (init, next_ts, begin, read_*, write_*, commit, rollback, gc, stats)
    17→//   - 내부 헬퍼 (가시성, 슬롯 할당, 충돌 감지)
    18→// ============================================================================
    19→
    20→module mvcc {
    21→    // ========================================================================
    22→    // 상수 정의
    23→    // ========================================================================
    24→
    25→    const MAX_VERSIONS: i32 = 2048;      // 최대 버전 개수
    26→    const MAX_ACTIVE_TX: i32 = 64;       // 최대 활성 트랜잭션 개수
    27→    const MVCC_TS_INF: i64 = -1;         // 무한 타임스탬프 (아직 삭제 안됨)
    28→
    29→    // 연산 타입
    30→    const VER_OP_INSERT: i32 = 1;
    31→    const VER_OP_UPDATE: i32 = 2;
    32→    const VER_OP_DELETE: i32 = 3;
    33→
    34→    // 에러 코드
    35→    const MVCC_OK:              i32 = 0;
    36→    const MVCC_ERR_NOT_FOUND:   i32 = 70;
    37→    const MVCC_ERR_CONFLICT:    i32 = 71;
    38→    const MVCC_ERR_FULL:        i32 = 72;
    39→    const MVCC_ERR_INVALID:     i32 = 73;
    40→
    41→    // ========================================================================
    42→    // 데이터 구조체
    43→    // ========================================================================
    44→
    45→    // VersionEntry: 단일 행의 단일 열에 대한 버전 정보
    46→    struct VersionEntry {
    47→        row_id:       i64;     // 행 ID
    48→        col_idx:      i32;     // 열 인덱스 (-1: INSERT/DELETE)
    49→        val_int:      i64;     // 정수 값
    50→        val_str:      string;  // 문자열 값
    51→        val_bool:     bool;    // 불린 값
    52→        op_type:      i32;     // VER_OP_*
    53→        created_ts:   i64;     // 생성 타임스탐프 (커밋 후 설정)
    54→        deleted_ts:   i64;     // 삭제 타임스탐프 (다음 버전 커밋 시 설정, MVCC_TS_INF 초기값)
    55→        tx_id:        i64;     // 트랜잭션 ID
    56→        is_used:      bool;    // 슬롯 사용 여부
    57→        is_committed: bool;    // 커밋됨 여부
    58→    }
    59→
    60→    // VersionStore: 모든 버전을 관리하는 저장소
    61→    struct VersionStore {
    62→        versions:     [VersionEntry];
    63→        version_count: i32;
    64→        next_slot:    i32;
    65→    }
    66→
    67→    // 전역 상태
    68→    let g_global_ts: i64 = 1;          // 글로벌 타임스탬프 (계속 증가)
    69→    let g_version_store: VersionStore = VersionStore{
    70→        versions:      make([VersionEntry], 1),  // 임시, init()에서 올바르게 설정
    71→        version_count: 0,
    72→        next_slot:     0,
    73→    };
    74→
    75→    // ========================================================================
    76→    // 공개 API - 초기화
    77→    // ========================================================================
    78→
    79→    func mvcc_init() -> i32 {
    80→        g_version_store.versions = make([VersionEntry], MAX_VERSIONS);
    81→        g_version_store.version_count = 0;
    82→        g_version_store.next_slot = 0;
    83→        return MVCC_OK;
    84→    }
    85→
    86→    // ========================================================================
    87→    // 공개 API - 타임스탬프
    88→    // ========================================================================
    89→
    90→    // 다음 타임스탬프 획득 및 증가
    91→    func mvcc_next_ts() -> i64 {
    92→        let ret = g_global_ts;
    93→        g_global_ts = g_global_ts + 1;
    94→        return ret;
    95→    }
    96→
    97→    // ========================================================================
    98→    // 공개 API - 트랜잭션 시작
    99→    // ========================================================================
   100→
   101→    // 트랜잭션 시작: 스냅샷 타임스탐프 반환
   102→    func mvcc_begin(tx_id: i64) -> (i64, i32) {
   103→        let snap_ts = mvcc_next_ts();
   104→        return (snap_ts, MVCC_OK);
   105→    }
   106→
   107→    // ========================================================================
   108→    // 공개 API - 읽기
   109→    // ========================================================================
   110→
   111→    // 정수 값 읽기
   112→    func mvcc_read_int(vs: *VersionStore, row_id: i64, col_idx: i32, snap_ts: i64, tx_id: i64) -> (i64, i32, i32) {
   113→        let i = 0;
   114→        for i = 0; i < vs.version_count; i = i + 1 {
   115→            let ver = vs.versions[i];
   116→            if ver.is_used && ver.row_id == row_id && ver.col_idx == col_idx {
   117→                if is_version_visible(ver, snap_ts, tx_id) {
   118→                    return (ver.val_int, i, MVCC_OK);
   119→                }
   120→            }
   121→        }
   122→        return (0, -1, MVCC_ERR_NOT_FOUND);
   123→    }
   124→
   125→    // 문자열 값 읽기
   126→    func mvcc_read_str(vs: *VersionStore, row_id: i64, col_idx: i32, snap_ts: i64, tx_id: i64) -> (string, i32, i32) {
   127→        let i = 0;
   128→        for i = 0; i < vs.version_count; i = i + 1 {
   129→            let ver = vs.versions[i];
   130→            if ver.is_used && ver.row_id == row_id && ver.col_idx == col_idx {
   131→                if is_version_visible(ver, snap_ts, tx_id) {
   132→                    return (ver.val_str, i, MVCC_OK);
   133→                }
   134→            }
   135→        }
   136→        return ("", -1, MVCC_ERR_NOT_FOUND);
   137→    }
   138→
   139→    // 불린 값 읽기
   140→    func mvcc_read_bool(vs: *VersionStore, row_id: i64, col_idx: i32, snap_ts: i64, tx_id: i64) -> (bool, i32, i32) {
   141→        let i = 0;
   142→        for i = 0; i < vs.version_count; i = i + 1 {
   143→            let ver = vs.versions[i];
   144→            if ver.is_used && ver.row_id == row_id && ver.col_idx == col_idx {
   145→                if is_version_visible(ver, snap_ts, tx_id) {
   146→                    return (ver.val_bool, i, MVCC_OK);
   147→                }
   148→            }
   149→        }
   150→        return (false, -1, MVCC_ERR_NOT_FOUND);
   151→    }
   152→
   153→    // ========================================================================
   154→    // 공개 API - 행 가시성
   155→    // ========================================================================
   156→
   157→    // 행이 주어진 스냅샷에서 보이는지 확인
   158→    func mvcc_row_visible(vs: *VersionStore, row_id: i64, snap_ts: i64, tx_id: i64) -> bool {
   159→        let i = 0;
   160→        let insert_visible = false;
   161→        let delete_visible = false;
   162→
   163→        for i = 0; i < vs.version_count; i = i + 1 {
   164→            let ver = vs.versions[i];
   165→            if !ver.is_used {
   166→                continue;
   167→            }
   168→
   169→            if ver.row_id == row_id && ver.col_idx == -1 {
   170→                if ver.op_type == VER_OP_INSERT {
   171→                    if is_version_visible(ver, snap_ts, tx_id) {
   172→                        insert_visible = true;
   173→                    }
   174→                } else if ver.op_type == VER_OP_DELETE {
   175→                    if is_version_visible(ver, snap_ts, tx_id) {
   176→                        delete_visible = true;
   177→                    }
   178→                }
   179→            }
   180→        }
   181→
   182→        return insert_visible && !delete_visible;
   183→    }
   184→
   185→    // ========================================================================
   186→    // 공개 API - 쓰기
   187→    // ========================================================================
   188→
   189→    // 정수 값 쓰기
   190→    func mvcc_write_int(vs: *VersionStore, row_id: i64, col_idx: i32, val: i64, tx_id: i64, snap_ts: i64) -> (i32, i32) {
   191→        // 충돌 검사
   192→        if has_write_conflict(vs, row_id, col_idx, tx_id) {
   193→            return (-1, MVCC_ERR_CONFLICT);
   194→        }
   195→
   196→        // 슬롯 할당
   197→        let slot, allocated = vs_alloc_slot(vs);
   198→        if !allocated {
   199→            return (-1, MVCC_ERR_FULL);
   200→        }
   201→
   202→        // 버전 작성
   203→        vs.versions[slot] = VersionEntry{
   204→            row_id:       row_id,
   205→            col_idx:      col_idx,
   206→            val_int:      val,
   207→            val_str:      "",
   208→            val_bool:     false,
   209→            op_type:      VER_OP_UPDATE,
   210→            created_ts:   0,
   211→            deleted_ts:   MVCC_TS_INF,
   212→            tx_id:        tx_id,
   213→            is_used:      true,
   214→            is_committed: false,
   215→        };
   216→
   217→        vs.version_count = vs.version_count + 1;
   218→        return (slot, MVCC_OK);
   219→    }
   220→
   221→    // 문자열 값 쓰기
   222→    func mvcc_write_str(vs: *VersionStore, row_id: i64, col_idx: i32, val: string, tx_id: i64, snap_ts: i64) -> (i32, i32) {
   223→        if has_write_conflict(vs, row_id, col_idx, tx_id) {
