   314→
   315→        vs.versions[slot] = VersionEntry{
   316→            row_id:       row_id,
   317→            col_idx:      -1,
   318→            val_int:      0,
   319→            val_str:      "",
   320→            val_bool:     false,
   321→            op_type:      VER_OP_DELETE,
   322→            created_ts:   0,
   323→            deleted_ts:   MVCC_TS_INF,
   324→            tx_id:        tx_id,
   325→            is_used:      true,
   326→            is_committed: false,
   327→        };
   328→
   329→        vs.version_count = vs.version_count + 1;
   330→        return (slot, MVCC_OK);
   331→    }
   332→
   333→    // ========================================================================
   334→    // 공개 API - 커밋/롤백
   335→    // ========================================================================
   336→
   337→    // 트랜잭션 커밋
   338→    func mvcc_commit(vs: *VersionStore, tx_id: i64, commit_ts: i64) -> i32 {
   339→        let i = 0;
   340→        for i = 0; i < vs.version_count; i = i + 1 {
   341→            if vs.versions[i].is_used && vs.versions[i].tx_id == tx_id {
   342→                // 현재 버전 커밋
   343→                vs.versions[i].is_committed = true;
   344→                vs.versions[i].created_ts = commit_ts;
   345→
   346→                // 이전 버전의 deleted_ts 설정
   347→                let j = 0;
   348→                for j = 0; j < i; j = j + 1 {
   349→                    let prev = vs.versions[j];
   350→                    if prev.is_used && prev.row_id == vs.versions[i].row_id &&
   351→                       prev.col_idx == vs.versions[i].col_idx && prev.is_committed &&
   352→                       prev.deleted_ts == MVCC_TS_INF {
   353→                        vs.versions[j].deleted_ts = commit_ts;
   354→                    }
   355→                }
   356→            }
   357→        }
   358→        return MVCC_OK;
   359→    }
   360→
   361→    // 트랜잭션 롤백
   362→    func mvcc_rollback(vs: *VersionStore, tx_id: i64) -> i32 {
   363→        let i = 0;
   364→        for i = 0; i < vs.version_count; i = i + 1 {
   365→            if vs.versions[i].is_used && vs.versions[i].tx_id == tx_id {
   366→                vs.versions[i].is_used = false;
   367→                vs.version_count = vs.version_count - 1;
   368→            }
   369→        }
   370→        return MVCC_OK;
   371→    }
   372→
   373→    // ========================================================================
   374→    // 공개 API - 가비지 컬렉션
   375→    // ========================================================================
   376→
   377→    // 오래된 버전 삭제 (min_visible_ts 이전 버전)
   378→    func mvcc_gc(vs: *VersionStore, min_visible_ts: i64) -> i32 {
   379→        let i = 0;
   380→        for i = 0; i < vs.version_count; i = i + 1 {
   381→            let ver = vs.versions[i];
   382→            if ver.is_used && ver.deleted_ts < min_visible_ts && ver.deleted_ts != MVCC_TS_INF {
   383→                vs.versions[i].is_used = false;
   384→                vs.version_count = vs.version_count - 1;
   385→            }
   386→        }
   387→        return MVCC_OK;
   388→    }
   389→
   390→    // ========================================================================
   391→    // 공개 API - 통계
   392→    // ========================================================================
   393→
   394→    func mvcc_stats(vs: *VersionStore) -> string {
   395→        return "VersionStore: " + i32_to_str(vs.version_count) + "/" + i32_to_str(MAX_VERSIONS);
   396→    }
