   398→    // ========================================================================
   399→    // 내부 헬퍼 함수
   400→    // ========================================================================
   401→
   402→    // 버전이 주어진 스냅샷에서 보이는지 확인
   403→    @inline
   404→    func is_version_visible(ver: VersionEntry, snap_ts: i64, tx_id: i64) -> bool {
   405→        // 같은 트랜잭션이면 항상 보임
   406→        if ver.tx_id == tx_id {
   407→            return true;
   408→        }
   409→
   410→        // 커밋되지 않았으면 안 보임
   411→        if !ver.is_committed {
   412→            return false;
   413→        }
   414→
   415→        // 생성 타임스탐프가 스냅샷보다 크면 안 보임
   416→        if ver.created_ts > snap_ts {
   417→            return false;
   418→        }
   419→
   420→        // 삭제되지 않았으면 보임
   421→        if ver.deleted_ts == MVCC_TS_INF {
   422→            return true;
   423→        }
   424→
   425→        // 삭제 타임스탐프가 스냅샷보다 크면 보임 (아직 삭제 전)
   426→        if ver.deleted_ts > snap_ts {
   427→            return true;
   428→        }
   429→
   430→        return false;
   431→    }
   432→
   433→    // 빈 슬롯 할당 (원형 버퍼)
   434→    func vs_alloc_slot(vs: *VersionStore) -> (i32, bool) {
   435→        let attempt = 0;
   436→        for attempt = 0; attempt < MAX_VERSIONS; attempt = attempt + 1 {
   437→            let slot = vs.next_slot;
   438→            vs.next_slot = (vs.next_slot + 1) % MAX_VERSIONS;
   439→
   440→            if !vs.versions[slot].is_used {
   441→                return (slot, true);
   442→            }
   443→        }
   444→        return (-1, false);
   445→    }
   446→
   447→    // 쓰기 충돌 감지
   448→    func has_write_conflict(vs: *VersionStore, row_id: i64, col_idx: i32, tx_id: i64) -> bool {
   449→        let i = 0;
   450→        for i = 0; i < vs.version_count; i = i + 1 {
   451→            let ver = vs.versions[i];
   452→            if ver.is_used && ver.row_id == row_id && ver.col_idx == col_idx &&
   453→               ver.tx_id != tx_id && !ver.is_committed {
   454→                return true;
   455→            }
   456→        }
   457→        return false;
   458→    }
