   463→
   464→    @inline
   465→    func i32_to_str(n: i32) -> string {
   466→        if n == 0 { return "0"; }
   467→        if n == 1 { return "1"; }
   468→        if n == 2 { return "2"; }
   469→        if n == 3 { return "3"; }
   470→        if n == 4 { return "4"; }
   471→        if n == 5 { return "5"; }
   472→        if n == 6 { return "6"; }
   473→        if n == 7 { return "7"; }
   474→        if n == 8 { return "8"; }
   475→        if n == 9 { return "9"; }
   476→        if n < 0 { return "-" + i32_to_str(-n); }
   477→        let d = n / 10;
   478→        let r = n % 10;
   479→        return i32_to_str(d) + i32_to_str(r);
   480→    }
   481→
   482→    @inline
   483→    func i64_to_str(n: i64) -> string {
   484→        if n == 0 { return "0"; }
   485→        if n < 0 { return "-" + i64_to_str(-n); }
   486→        return i32_to_str(i32(n));
   487→    }
