     2→// FreeLang Snapshot 모듈 - MVCC 가시성 관리
     3→// ============================================================================
     4→// 목표: 트랜잭션별 가시성 스냅샷 관리 및 MVCC 기반 행 접근성 판단
     5→// 원리:
     6→//   1. Snapshot: 특정 시점의 모든 활성 트랜잭션 ID 저장
     7→//   2. MVCC 가시성: created_ts <= snap_ts AND deleted_ts > snap_ts
     8→//   3. 활성 트랜잭션 필터: 스냅샷 생성 시점에 활성이던 tx는 보이지 않음
     9→//   4. O(1) 제거: 배열 마지막 원소로 교환 후 제거
    10→// 구조:
    11→//   - 상수 정의 (제한값, 에러 코드)
    12→//   - Snapshot, SnapshotPool 구조체
    13→//   - 전역 상태 (풀, 활성 트랜잭션 추적)
    14→//   - 공개 API 함수 8개
    15→//   - 내부 헬퍼 함수 3개
    16→// ============================================================================
    17→
    18→module snapshot {
    19→    // === 상수 ===
    20→
    21→    // 제한값
    22→    const MAX_SNAPSHOTS:      i32 = 128;
    23→    const MAX_SNAP_ACTIVE_TX: i32 = 64;
    24→    const MAX_ACTIVE_TX:      i32 = 64;
    25→
    26→    // 에러 코드
    27→    const SNAP_OK:            i32 = 0;
    28→    const SNAP_ERR_FULL:      i32 = 80;
    29→    const SNAP_ERR_NOT_FOUND: i32 = 81;
    30→
    31→    // === 데이터 구조체 ===
    32→
    33→    // 스냅샷: 특정 시점의 가시성 정보
    34→    struct Snapshot {
    35→        snap_id:      i32;                           // 스냅샷 ID (슬롯 인덱스)
    36→        snap_ts:      i64;                           // 논리 타임스탬프
    37→        tx_id:        i64;                           // 스냅샷 생성 트랜잭션 ID
    38→        active_tx_ids: [i64];                         // 스냅샷 생성 시점의 활성 tx 배열
    39→        active_count: i32;                           // 실제 활성 tx 개수
    40→        is_used:      bool;                          // 슬롯 사용 여부
    41→    }
    42→
    43→    // 스냅샷 풀
    44→    struct SnapshotPool {
    45→        snaps:      [Snapshot];
    46→        snap_count: i32;
    47→    }
    48→
    49→    // === 전역 상태 ===
    50→
    51→    // 스냅샷 풀 (전역 단일 인스턴스)
    52→    let g_snapshot_pool: SnapshotPool = SnapshotPool{
    53→        snaps:      make([Snapshot], MAX_SNAPSHOTS),
    54→        snap_count: 0,
    55→    };
    56→
    57→    // 현재 활성 트랜잭션 추적
    58→    let g_active_tx_ids:      [i64] = make([i64], MAX_ACTIVE_TX);
    59→    let g_active_tx_snap_ts:  [i64] = make([i64], MAX_ACTIVE_TX);
    60→    let g_active_tx_count:    i32   = 0;
    61→
    62→    // === 공개 API ===
    63→
    64→    // snapshot_init: 스냅샷 시스템 초기화
    65→    func snapshot_init() -> i32 {
    66→        g_snapshot_pool.snaps = make([Snapshot], MAX_SNAPSHOTS);
    67→        g_snapshot_pool.snap_count = 0;
    68→
    69→        g_active_tx_ids = make([i64], MAX_ACTIVE_TX);
    70→        g_active_tx_snap_ts = make([i64], MAX_ACTIVE_TX);
    71→        g_active_tx_count = 0;
    72→
    73→        return SNAP_OK;
    74→    }
    75→
    76→    // snapshot_create: 새로운 스냅샷 생성
    77→    // 반환: (snap_id, 에러코드)
    78→    // - snap_id: 0 이상이면 성공, -1이면 실패
    79→    func snapshot_create(tx_id: i64, snap_ts: i64) -> (i32, i32) {
    80→        let slot, alloc_ok = sp_alloc_slot(&g_snapshot_pool);
    81→        if !alloc_ok {
    82→            return (-1, SNAP_ERR_FULL);
    83→        }
    84→
    85→        // 새 스냅샷 생성
    86→        let snap: Snapshot;
    87→        snap.snap_id = slot;
    88→        snap.snap_ts = snap_ts;
    89→        snap.tx_id = tx_id;
    90→        snap.active_tx_ids = make([i64], MAX_SNAP_ACTIVE_TX);
    91→        snap.active_count = 0;
    92→        snap.is_used = true;
    93→
    94→        // 현재 활성 트랜잭션 복사
    95→        let i = 0;
    96→        for i = 0; i < g_active_tx_count && i < MAX_SNAP_ACTIVE_TX; i = i + 1 {
    97→            snap.active_tx_ids[i] = g_active_tx_ids[i];
    98→        }
    99→        snap.active_count = i;
   100→
   101→        // 풀에 저장
   102→        g_snapshot_pool.snaps[slot] = snap;
   103→        g_snapshot_pool.snap_count = g_snapshot_pool.snap_count + 1;
   104→
   105→        return (slot, SNAP_OK);
   106→    }
   107→
   108→    // snapshot_is_visible: 행이 스냅샷에서 보이는지 판단 (MVCC)
   109→    // 파라미터:
   110→    //   snap_id: 스냅샷 ID
   111→    //   created_ts: 행의 생성 타임스탬프
   112→    //   deleted_ts: 행의 삭제 타임스탬프 (-1 = 미삭제)
   113→    //   creator_tx_id: 행을 생성한 트랜잭션 ID
   114→    //   my_tx_id: 현재 트랜잭션 ID
   115→    func snapshot_is_visible(snap_id: i32, created_ts: i64, deleted_ts: i64,
   116→                             creator_tx_id: i64, my_tx_id: i64) -> bool {
   117→        if snap_id < 0 || snap_id >= MAX_SNAPSHOTS {
   118→            return false;
   119→        }
   120→
   121→        let snap = g_snapshot_pool.snaps[snap_id];
   122→        if !snap.is_used {
   123→            return false;
   124→        }
   125→
   126→        // 기본 MVCC 가시성 판정
   127→        let visible_mvcc = created_ts <= snap.snap_ts &&
   128→                          (deleted_ts == -1 || deleted_ts > snap.snap_ts);
   129→
   130→        if !visible_mvcc {
   131→            return false;
   132→        }
   133→
   134→        // 추가 조건: creator_tx가 스냅샷 생성 시점에 활성이었는가?
   135→        if creator_tx_id != my_tx_id {
   136→            let has_active = snap_has_active_tx(snap, creator_tx_id);
   137→            if has_active {
   138→                // creator tx가 아직 커밋되지 않았음 → 안 보임
   139→                return false;
   140→            }
   141→        }
   142→
   143→        return true;
   144→    }
   145→
   146→    // snapshot_destroy: 스냅샷 파괴 및 트랜잭션 등록 해제
   147→    func snapshot_destroy(snap_id: i32, tx_id: i64) -> i32 {
   148→        if snap_id < 0 || snap_id >= MAX_SNAPSHOTS {
   149→            return SNAP_ERR_NOT_FOUND;
   150→        }
   151→
   152→        g_snapshot_pool.snaps[snap_id].is_used = false;
   153→        g_snapshot_pool.snap_count = g_snapshot_pool.snap_count - 1;
   154→
   155→        snapshot_unregister_tx(tx_id);
   156→
   157→        return SNAP_OK;
   158→    }
   159→
   160→    // snapshot_register_tx: 활성 트랜잭션 등록
   161→    func snapshot_register_tx(tx_id: i64, snap_ts: i64) -> i32 {
   162→        if g_active_tx_count >= MAX_ACTIVE_TX {
   163→            return SNAP_ERR_FULL;
   164→        }
   165→
   166→        g_active_tx_ids[g_active_tx_count] = tx_id;
   167→        g_active_tx_snap_ts[g_active_tx_count] = snap_ts;
   168→        g_active_tx_count = g_active_tx_count + 1;
   169→
   170→        return SNAP_OK;
   171→    }
   172→
   173→    // snapshot_unregister_tx: 활성 트랜잭션 제거 (O(1))
   174→    func snapshot_unregister_tx(tx_id: i64) -> i32 {
   175→        let idx, found = active_tx_find(tx_id);
   176→        if !found {
   177→            return SNAP_ERR_NOT_FOUND;
   178→        }
   179→
   180→        // 마지막 원소를 현재 위치로 옮기기
   181→        if idx < g_active_tx_count - 1 {
   182→            g_active_tx_ids[idx] = g_active_tx_ids[g_active_tx_count - 1];
   183→            g_active_tx_snap_ts[idx] = g_active_tx_snap_ts[g_active_tx_count - 1];
   184→        }
   185→
   186→        g_active_tx_count = g_active_tx_count - 1;
   187→        return SNAP_OK;
   188→    }
   189→
   190→    // snapshot_min_visible_ts: 현재 가시성의 최소 타임스탬프
   191→    // GC 대상 결정에 사용 (이 값보다 작은 커밋은 안전하게 GC 가능)
   192→    func snapshot_min_visible_ts() -> i64 {
   193→        if g_active_tx_count == 0 {
   194→            // 활성 트랜잭션 없음 → 매우 큰 값 반환
   195→            return 9223372036854775807;  // i64 max
   196→        }
   197→
   198→        // 활성 트랜잭션의 최소 타임스탐프 찾기
   199→        let min_ts = g_active_tx_snap_ts[0];
   200→        let i = 1;
   201→        for i = 1; i < g_active_tx_count; i = i + 1 {
   202→            let ts = g_active_tx_snap_ts[i];
   203→            if ts < min_ts {
   204→                min_ts = ts;
   205→            }
   206→        }
   207→
   208→        return min_ts;
   209→    }
   210→
   211→    // snapshot_stats: 통계 문자열 생성
   212→    func snapshot_stats() -> string {
   213→        let snap_info = "SnapshotPool: ";
   214→        snap_info = snap_info + i32_to_string(g_snapshot_pool.snap_count);
   215→        snap_info = snap_info + "/";
   216→        snap_info = snap_info + i32_to_string(MAX_SNAPSHOTS);
   217→        snap_info = snap_info + ", ActiveTx: ";
   218→        snap_info = snap_info + i32_to_string(g_active_tx_count);
   219→
   220→        return snap_info;
   221→    }
   222→
   223→    // === 내부 헬퍼 함수 ===
   224→
   225→    // sp_alloc_slot: 스냅샷 풀에서 빈 슬롯 할당
   226→    func sp_alloc_slot(sp: *SnapshotPool) -> (i32, bool) {
   227→        let i = 0;
   228→        for i = 0; i < MAX_SNAPSHOTS; i = i + 1 {
   229→            if !sp.snaps[i].is_used {
   230→                return (i, true);
   231→            }
   232→        }
   233→        return (-1, false);
   234→    }
   235→
   236→    // snap_has_active_tx: 스냅샷의 활성 tx 리스트에 특정 tx가 있는지 확인
   237→    @inline
   238→    func snap_has_active_tx(snap: Snapshot, tx_id: i64) -> bool {
   239→        let i = 0;
   240→        for i = 0; i < snap.active_count; i = i + 1 {
   241→            if snap.active_tx_ids[i] == tx_id {
   242→                return true;
   243→            }
   244→        }
   245→        return false;
